import { ViewTransition } from 'react'

// Slides page content left/right based on the transition type set by the
// navigating <Link>. Untyped transitions (browser back/forward, Suspense
// reveals, refreshes) don't slide.
const directional = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

export function DirectionalTransition({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <ViewTransition enter={directional} exit={directional} default="none">
      {children}
    </ViewTransition>
  )
}

